const assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),vscode=require('vscode'),{createHash}=require('node:crypto'),{Cdp,sleep}=require('./cdp.cjs');
exports.run=async()=>{
 const fixture=await vscode.extensions.getExtension('synthetic.current-plugin-capture').activate(),cdp=await Cdp.connect(Number(process.env.AG_CAPTURE_CDP_PORT)),evidence=process.env.AG_CAPTURE_EVIDENCE,checks={},shots=[],searchDebug=[];let ui;
 const read=e=>cdp.eval(e,ui),until=async(fn,label)=>{for(let i=0;i<200;i++){if(await fn())return;await sleep(40)}throw Error('Timeout: '+label)};
 const main=await cdp.find('.monaco-workbench');
 const capture=async(name)=>{await vscode.commands.executeCommand('notifications.clearAll');await sleep(100);const text=await read('document.body.innerText');assert.doesNotMatch(text,/Bearer |refresh_token|access_token|csrfToken/i);const r=await cdp.send('Page.captureScreenshot',{format:'png'},main.session),bytes=Buffer.from(r.data,'base64');await fs.writeFile(path.join(evidence,name+'.png'),bytes);shots.push({file:name+'.png',bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),language:await read('document.documentElement.lang'),theme:vscode.workspace.getConfiguration('workbench').get('colorTheme'),webviewWidth:await read('innerWidth')});};
 try{
 await vscode.commands.executeCommand('workbench.action.closeSidebar');await vscode.commands.executeCommand('antigravityAccounts.workbench.open');ui=await cdp.find('body[data-wb-surface="editor"]');await until(()=>read('document.querySelectorAll(".account").length===4&&typeof synchronized!=="undefined"&&synchronized'),'editor account cards and ready handshake');
 await vscode.commands.executeCommand('antigravityAccounts.workbench.open');assert.equal(vscode.window.tabGroups.all.flatMap(g=>g.tabs).filter(t=>t.label==='账号与额度').length,1);checks.repeatedEditorOpenReusesPanel=true;
 await read('document.querySelector("#quota-search").value="1";document.querySelector("#quota-search").dispatchEvent(new Event("input",{bubbles:true}));document.querySelector("#quota-search").focus()');
 await read('window.__searchNode=document.querySelector("#quota-search")');searchDebug.push({stage:'INPUT',state:await read('({dom:document.querySelector("#quota-search").value,controls,stored:api.getState(),ready:synchronized})')});await fs.writeFile(path.join(evidence,'search-debug.json'),JSON.stringify(searchDebug,null,2));const a=fixture.accounts[0],query='[data-command="live.quota"][data-id="'+a.id+'"]';await cdp.click(ui,query);await until(()=>fixture.pending(),'held account query');searchDebug.push({stage:'QUERY',state:await read('({dom:document.querySelector("#quota-search").value,controls,stored:api.getState(),same:window.__searchNode===document.querySelector("#quota-search"),connected:window.__searchNode.isConnected})')});await fs.writeFile(path.join(evidence,'search-debug.json'),JSON.stringify(searchDebug,null,2));await read('document.querySelector('+JSON.stringify(query)+')?.click()');assert.equal(fixture.calls.length,1);
 await until(()=>read('!!document.querySelector(\'[data-command="live.quotaCancel"]\')'),'cancel control rendered');await cdp.click(ui,'[data-command="live.quotaCancel"]');await until(()=>!fixture.pending(),'cancelled account query');searchDebug.push({stage:'CANCEL',state:await read('({dom:document.querySelector("#quota-search").value,controls,stored:api.getState(),same:window.__searchNode===document.querySelector("#quota-search"),connected:window.__searchNode.isConnected})')});await fs.writeFile(path.join(evidence,'search-debug.json'),JSON.stringify(searchDebug,null,2));assert.equal(await read('document.querySelector("#quota-search").value'),'1');checks.cancelAndRepeatedQueryPreserveSearch=true;
 await cdp.send('Emulation.setDeviceMetricsOverride',{width:1600,height:1000,deviceScaleFactor:1,mobile:false},main.session);await until(()=>read('innerWidth>1050'),'wide editor');
 for(const theme of ['Light Modern','Dark Modern','Default High Contrast']){
  await vscode.workspace.getConfiguration('workbench').update('colorTheme',theme,vscode.ConfigurationTarget.Global);
  await vscode.commands.executeCommand('antigravityAccounts.workbench.open');ui=await cdp.find('body[data-wb-surface="editor"]');await read('document.querySelector("#quota-search").value="";document.querySelector("#quota-search").dispatchEvent(new Event("input",{bubbles:true}));document.querySelectorAll(".account details").forEach((d,i)=>d.open=i<1);window.scrollTo(0,0)');
  await until(()=>read('document.body.classList.contains('+JSON.stringify(theme.includes('Light')?'vscode-light':theme.includes('Contrast')?'vscode-high-contrast':'vscode-dark')+')'),'native theme '+theme);await capture(theme.includes('Light')?'accounts-light':theme.includes('Contrast')?'accounts-contrast':'accounts-dark');
  await vscode.commands.executeCommand('antigravityAccounts.images.open');ui=await cdp.find('#prompt');await until(()=>read('document.querySelector("#model").options.length>0'),'image catalog');await read('window.scrollTo(0,0)');await capture(theme.includes('Light')?'images-light':theme.includes('Contrast')?'images-contrast':'images-dark');
  await vscode.commands.executeCommand('antigravityAccounts.automation.open','tasks');ui=await cdp.find('#task-form');await capture(theme.includes('Light')?'schedules-light':theme.includes('Contrast')?'schedules-contrast':'schedules-dark');
  await read('document.querySelector("[data-automation-tab=alerts]").click()');await until(()=>read('!document.querySelector("#alerts-settings").hidden'),'alert section');await capture(theme.includes('Light')?'alerts-light':theme.includes('Contrast')?'alerts-contrast':'alerts-dark');
  await vscode.commands.executeCommand('antigravityAccounts.openSettings');ui=await cdp.find('#support-language');await capture(theme.includes('Light')?'settings-light':theme.includes('Contrast')?'settings-contrast':'settings-dark');
  await vscode.commands.executeCommand('antigravityAccounts.openHelp');ui=await cdp.find('body[data-wb-page=help]');await capture(theme.includes('Light')?'help-light':theme.includes('Contrast')?'help-contrast':'help-dark');
  await vscode.commands.executeCommand('antigravityAccounts.support.diagnostics');ui=await cdp.find('#support-host');await capture(theme.includes('Light')?'diagnostics-light':theme.includes('Contrast')?'diagnostics-contrast':'diagnostics-dark');
 }
 checks.productionPagesFollowLightAndDark=true;checks.highContrast=true;await vscode.workspace.getConfiguration('workbench').update('colorTheme','Dark Modern',vscode.ConfigurationTarget.Global);
 await vscode.commands.executeCommand('antigravityAccounts.images.open');ui=await cdp.find('#prompt');const draft='合成设计回归草稿 · 不发送';await read('document.querySelector("#prompt").value='+JSON.stringify(draft)+';document.querySelector("#prompt").dispatchEvent(new Event("input",{bubbles:true}))');
 await vscode.commands.executeCommand('antigravityAccounts.openSettings');ui=await cdp.find('#support-language');await read('document.querySelector("#support-language").value="en";document.querySelector("#support-language").dispatchEvent(new Event("change",{bubbles:true}))');await until(()=>read('document.documentElement.lang==="en"&&!document.querySelector("#support-language").disabled'),'global language settings');
 await vscode.commands.executeCommand('workbench.action.closeActiveEditor');await vscode.commands.executeCommand('antigravityAccounts.openSettings');ui=await cdp.find('#support-language');await until(()=>read('document.querySelector("#support-language").value==="en"'),'recreated settings uses global value');
 await vscode.commands.executeCommand('antigravityAccounts.images.open');ui=await cdp.find('#prompt');await until(()=>read('document.documentElement.lang==="en"'),'image global English');assert.equal(await read('document.querySelector("#prompt").value'),draft);await capture('images-english-dark');checks.globalLanguageAndRecreatedSettingsKeepDraft=true;
 await vscode.commands.executeCommand('antigravityAccounts.automation.open','tasks');ui=await cdp.find('#task-form');await read('document.querySelector("#timezone").value="Asia/Shanghai";document.querySelector("#times").value="08:30"');await read('document.querySelector("[data-automation-tab=alerts]").click();document.querySelector("[data-automation-tab=tasks]").click()');assert.equal(await read('document.querySelector("#times").value'),'08:30');assert.equal(await read('document.querySelector("#timezone").value'),'Asia/Shanghai');
 for(const mode of ['calendar','interval','cron','quota-recovery']){await read('document.querySelector("#mode").value='+JSON.stringify(mode)+';document.querySelector("#mode").dispatchEvent(new Event("change"))');assert.equal(await read('document.querySelector("[data-mode='+mode+']").hidden'),false);}
 checks.allFourModesAndSectionChangesKeepFields=true;
 await vscode.commands.executeCommand('antigravityAccounts.openSettings');ui=await cdp.find('#support-language');await read('document.querySelector("#support-language").value="zh-CN";document.querySelector("#support-language").dispatchEvent(new Event("change",{bubbles:true}))');await until(()=>read('document.documentElement.lang==="zh-CN"&&!document.querySelector("#support-language").disabled'),'restore Chinese');
 await vscode.commands.executeCommand('workbench.action.closeSidebar');await cdp.send('Emulation.setDeviceMetricsOverride',{width:560,height:900,deviceScaleFactor:1,mobile:false},main.session);
 for(const[command,selector,name,arg]of [['antigravityAccounts.workbench.open','body[data-wb-surface=editor]','accounts-narrow'],['antigravityAccounts.images.open','#prompt','images-narrow'],['antigravityAccounts.automation.open','#task-form','schedules-narrow','tasks'],['antigravityAccounts.automation.open','#alerts-settings','alerts-narrow','alerts'],['antigravityAccounts.openSettings','#support-language','settings-narrow'],['antigravityAccounts.openHelp','body[data-wb-page=help]','help-narrow'],['antigravityAccounts.support.diagnostics','#support-host','diagnostics-narrow']]){
  await vscode.commands.executeCommand(command,...(arg?[arg]:[]));ui=await cdp.find(selector);await until(()=>read('innerWidth<600'),'narrow '+name);await read('window.scrollTo(0,0)');const geometry=await read('({client:document.documentElement.clientWidth,scroll:document.documentElement.scrollWidth})');assert.ok(geometry.scroll<=geometry.client+1,name+JSON.stringify(geometry));await capture(name);
 }
 checks.narrowPagesNoOverflow=true;await cdp.send('Emulation.clearDeviceMetricsOverride',{},main.session);
 assert.equal(fixture.imageRuns(),0);assert.equal(fixture.wakeCalls(),0);assert.equal((await fixture.automation.store.read()).enabled,false);checks.noRealRequestsOrScheduling=true;
 await fs.writeFile(path.join(evidence,'capture-receipt.json'),JSON.stringify({passed:true,sourceCommit:process.env.AG_CAPTURE_COMMIT,vscode:vscode.version,checks,shots,productionUi:true,syntheticAccounts:true,realCredentials:false,googleRequests:false,imageModelRequests:0,wakeModelRequests:0},null,2));
 }finally{fixture.automation.engine.dispose();cdp.close()}
};
